/** Decode one corpus entry to bytes — the runtime-neutral spelling of readFileSync. */
export function corpusBytes(name: string): Uint8Array {
  const entry = PNG_CORPUS[name]
  if (!entry) throw new Error(`no such PNG fixture: ${name}`)
  const binary = atob(entry.base64)
  const out = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i)
  return out
}
